def tarjan(g):
    n = len(g)
    scc, s, p = [], [], []
    q = [i for i in range(n)]
    state = [0] * n
    while q:
        node = q.pop()
        if node < 0:
            d = state[~node] - 1
            if p[-1] > d:
                scc.append(s[d:])
                del s[d:]
                p.pop()
                for v in scc[-1]:
                    state[v] = -1
        elif state[node] > 0:
            while p[-1] > state[node]:
                p.pop()
        elif state[node] == 0:
            s.append(node)
            p.append(len(s))
            state[node] = len(s)
            q.append(~node)
            q.extend(g[node])
    return scc

