def topological_sort(G, indegree=None):

    N = len(G)
    if indegree is None:
        indegree = [0]*N
        for v in range(N):
            for adj in G[v]:
                indegree[adj] += 1

    deq = deque()
    for v in range(N):
        if indegree[v] == 0:
            deq.append(v)

    res = []
    while deq:
        v = deq.popleft()
        res.append(v)
        for adj in G[v]:
            indegree[adj] -= 1
            if indegree[adj] == 0:
                deq.append(adj)

    return res



